import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    pos = neg = zero = 0
    idx = 1
    for _ in range(n):
        val = int(data[idx])
        idx += 1
        if val > 0:
            pos += 1
        elif val < 0:
            neg += 1
        else:
            zero += 1
    print(pos)
    print(neg)
    print(zero)

if __name__ == "__main__":
    main()
